S('air-cargo-clearance-mumbai-sahar','Air Cargo Clearance at Mumbai Sahar Airport, 24x7 Desk | YAM Logistics',
 'Import and export air cargo clearance at Mumbai Sahar Air Cargo Complex (INBOM4). 24x7 desk, licensed customs broker R-7/92, mobile phone and electronics exports, dangerous goods.',
 'Air cargo clearance, Mumbai Sahar','AIR CARGO · MUMBAI SAHAR','Air cargo clearance at','Mumbai Sahar, 24x7.',
 'Mumbai is one of India’s busiest air cargo gateways, and our air cargo office sits inside the Sahar Air Cargo Complex in Andheri East. The desk is open round the clock, so cargo and documents that arrive after midnight are routine.',
 [('What we clear at Sahar',['Air imports of general cargo, electronics, spares, pharma and perishables, filed in advance on ICEGATE.','Air exports with shipping bill, let export order and airline handover, including mobile phones and electronics under our dedicated programme.','Dangerous goods, including lithium batteries, with the correct declaration and labels.','Urgent aircraft parts and time-critical cargo.']),
 ('Why a desk at the airport matters',['Cargo moves through the terminal on tight cut-offs. A broker with people in the building can fix a document, meet an officer or collect a release within minutes. Our office address is 406, 4th Floor, Rangoli Complex, Sahar Air Cargo Complex, Andheri (East), Mumbai 400099.']),
 ('Related guides and tools',['Read <a href="guides/air-freight-booking-steps" style="color:#0A6CC2">how to book air freight</a>, the <a href="guides/lithium-battery-shipping-guide" style="color:#0A6CC2">lithium battery guide</a> and <a href="mobile-phone-exports" style="color:#0A6CC2">mobile phone exports</a>. Track a flight with the <a href="tracking/" style="color:#0A6CC2">free AWB tracking pages</a>.'])],
 [('What is the customs code for Mumbai air cargo?','Sahar Air Cargo Complex is INBOM4 on Indian Customs documents.'),
  ('Do you work at night at Mumbai airport?','Yes. The desk is open 24x7 for urgent import and export cargo.'),
  ('Can you export mobile phones and electronics from Mumbai?','Yes. We have a dedicated programme, with the lithium battery paperwork and airline acceptance handled by us.')],
 [('air-freight','Air freight','Our full air service.'),('mobile-phone-exports','Mobile phone exports','From Mumbai airport.'),('guides/lithium-battery-shipping-guide','Lithium battery guide','Rules for air.')])
for code,city,st,extra in [('bengaluru','Bengaluru','INBLR4','Bengaluru is a hub for electronics, aerospace parts, pharma and software hardware, so time-sensitive and high value cargo is common.'),
 ('chennai','Chennai','INMAA4','Chennai is a gateway for automotive parts, electronics and exports to South East Asia and the Gulf.'),
 ('hyderabad','Hyderabad','INHYD4','Hyderabad handles a lot of pharma, vaccines and life-science cargo, which needs careful temperature and documentation control.'),
 ('ahmedabad','Ahmedabad','INAMD4','Ahmedabad serves the textile, chemical and pharma belt of Gujarat.')]:
    S('air-cargo-clearance-%s'%code,'Air Cargo Clearance at %s Airport (%s) | YAM Logistics'%(city,st),
     'Import and export air cargo clearance at %s airport, station code %s. Licensed customs broker R-7/92, advance filing, permissions checked, delivery to your premises.'%(city,st),
     'Air cargo clearance, %s'%city,'AIR CARGO · %s'%city.upper(),'Air cargo clearance at',' %s airport.'%city,
     '%s We clear air import and export cargo at %s airport (%s) as a licensed customs broker, with the same desk that can also book the flight.'%(extra,city,st),
     [('What we handle',['Bill of entry and shipping bill filing on ICEGATE, usually before the flight lands or departs.','HS classification, duty working and permissions such as BIS, FSSAI, WPC or drug licence, checked before you ship.','Examination, queries and release from the air cargo terminal.','Delivery to your factory or warehouse, and pickup for exports.']),
      ('How it works',['You send the invoice, packing list and airway bill details. We confirm the classification and the duty, file the document and follow the cargo. Read the full <a href="guides/customs-clearance-process-india" style="color:#0A6CC2">clearance process</a> and the guide to <a href="guides/air-freight-chargeable-weight-and-rates" style="color:#0A6CC2">air freight rates</a>.']),
      ('Other stations',['We also clear at Mumbai Sahar (24x7), Delhi IGI, Ahmedabad, Lucknow, Kochi, Kozhikode, Hyderabad, Chennai and Bengaluru, as well as the ports and Delhi depots. See <a href="customs-clearance-india" style="color:#0A6CC2">customs clearance in India</a>.'])],
     [('What is the station code for %s air cargo?'%city,'%s airport air cargo is %s on Indian Customs documents.'%(city,st)),
      ('Can you clear cargo that needs BIS or FSSAI?','Yes. We check the permission before the cargo ships and file it with the bill of entry.'),
      ('Do you deliver after clearance?','Yes. We arrange delivery to your premises, or you can collect from the terminal.')],
     [('air-freight-services-india','Air freight services','Import and export by air.'),('air-cargo-clearance-delhi-igi','Delhi IGI air cargo','Our Delhi page.'),('guides/volumetric-weight-air-freight','Volumetric weight','How air cargo is charged.')])
S('electronics-import-clearance-india','Electronics Import Clearance in India: BIS, WPC and Duty | YAM Logistics',
 'How to clear electronics and IT hardware through Indian Customs: BIS registration, WPC licence, duty, and documents. Licensed customs broker R-7/92.',
 'Electronics import clearance','ELECTRONICS · IMPORT CLEARANCE','Electronics import clearance','in India.',
 'Electronics are among the most common imports that get held at the port, usually for a missing registration rather than a problem with the cargo. A licensed broker can check the rules before you order.',
 [('What electronics usually need',['<b>BIS registration</b> for products on the compulsory registration list. The manufacturer registers the product and the importer shows the number at clearance.','<b>WPC approval</b> for devices with radio parts such as Wi-Fi, Bluetooth or cellular modules.','<b>Correct HS code</b> and the right duty, including any cess or exemption.','<b>E-waste and battery rules</b> may apply to the importer.']),
 ('How to avoid a held shipment',['Check the registration before you place the order. Ask the supplier for the registration number and the test report. Send the draft invoice and the product details to your broker. If a registration is missing, fix it before shipping, because the cargo may otherwise be held, returned or destroyed.']),
 ('Tools',['Use the <a href="customs-duty-calculator" style="color:#0A6CC2">duty calculator</a> and the <a href="import-duty/" style="color:#0A6CC2">import duty pages by HS code</a> for the rate, and the guide to <a href="guides/bis-certification-for-imports" style="color:#0A6CC2">BIS certification</a> for the process.'])],
 [('Do all electronics need BIS?','No, only the products on the compulsory registration list. Ask your broker to check your exact product.'),
  ('Can I import samples without BIS?','There are exemptions for samples and R&D in some cases, with conditions. Check before you ship.'),
  ('Can you clear electronics by air?','Yes. We clear at Mumbai, Delhi, Bengaluru, Chennai, Hyderabad and other airports, and at the ports.')],
 [('guides/bis-certification-for-imports','BIS certification','What it is and how to plan.'),('customs-clearance-india','Customs clearance in India','Full service.'),('air-freight-services-india','Air freight','Fast routes for electronics.')])
S('food-import-clearance-india','Food Import Clearance in India: FSSAI and Customs | YAM Logistics',
 'How to clear food and beverage imports through Indian Customs: FSSAI licence, NOC, labelling, shelf life, and documents. Licensed customs broker R-7/92.',
 'Food import clearance','FOOD IMPORTS · FSSAI','Food import clearance','in India.',
 'Food imports are cleared by two authorities at once: Customs for duty, and the food safety authority for safety and labelling. Getting both in order before the cargo lands is the key to avoiding delay.',
 [('What you need',['An importer licence under the food safety rules before the cargo arrives.','Product details and labelling that meet the Indian rules, including shelf life remaining at arrival.','Documents from the exporter such as a certificate of analysis and a health or origin certificate where required.','The right HS code and the duty on it.']),
 ('At the port',['The food safety authority at the port or airport examines the documents and may draw samples for testing. Customs clears the goods once the food authority has cleared them. Test results can take days, so plan storage and free days.']),
 ('How we help',['We check the product and label before the order, file the bill of entry in advance, coordinate with the food authority and handle storage and delivery. See the guide to <a href="guides/fssai-import-clearance" style="color:#0A6CC2">FSSAI import clearance</a> and, for cold chain, the <a href="guides/reefer-container-guide" style="color:#0A6CC2">reefer container guide</a>.'])],
 [('Do I need a licence to import food?','Yes, the importer needs the licence from the food safety authority before filing the bill of entry.'),
  ('How long does food clearance take?','If documents and labels are correct, a few days. Sampling and testing add time.'),
  ('Can you handle reefer cargo?','Yes. We plan the cold chain and keep the clearance time short, since power and storage at the port cost money.')],
 [('guides/fssai-import-clearance','FSSAI import clearance','The process in detail.'),('guides/perishable-cargo-by-air-and-sea','Perishable cargo','By air and sea.'),('customs-clearance-india','Customs clearance in India','Full service.')])
S('machinery-import-clearance-india','Machinery Import Clearance in India: Duty, EPCG and Second-Hand | YAM Logistics',
 'How to clear industrial machinery and spare parts through Indian Customs: classification, duty, EPCG, second-hand rules, project cargo. Licensed customs broker R-7/92.',
 'Machinery import clearance','MACHINERY · PROJECT CARGO','Machinery import clearance','in India.',
 'Machinery imports mix classification questions, scheme benefits and heavy logistics. Done well, the duty can be much lower than the standard rate, and the cargo can move without surprises.',
 [('What to settle first',['The exact classification, especially for machines with parts, accessories and software.','Whether a scheme lowers the duty, such as EPCG for exporters.','Whether the machine is new or second-hand, since second-hand machinery has its own conditions.','Whether the cargo is over-dimensional and needs project handling.']),
 ('Logistics',['Large and heavy machinery often needs open-top or flat-rack containers, or break-bulk. See the guides to <a href="guides/open-top-flat-rack-out-of-gauge-cargo" style="color:#0A6CC2">out-of-gauge cargo</a> and <a href="guides/project-cargo-and-break-bulk-guide" style="color:#0A6CC2">project cargo</a>.']),
 ('What we do',['Classify, work out the duty, check the scheme, file in advance and coordinate the heavy transport. See <a href="guides/advance-authorisation-and-epcg" style="color:#0A6CC2">advance authorisation and EPCG</a> for the schemes.'])],
 [('Can I import second-hand machinery?','In many cases yes, with conditions such as an inspection or a certificate on age and value. Ask before you buy.'),
  ('What is EPCG?','A scheme that lets an exporter import capital goods at a reduced or zero duty in return for an export obligation.'),
  ('Do you handle oversize cargo?','Yes. We plan the lifting, lashing and permits with our project cargo partners.')],
 [('guides/advance-authorisation-and-epcg','Advance authorisation and EPCG','Duty-saving schemes.'),('guides/project-cargo-and-break-bulk-guide','Project cargo','Heavy and oversize.'),('ocean-freight','Ocean freight','FCL, LCL and project.')])
S('customs-clearance-mumbai','Customs Clearance in Mumbai: Nhava Sheva and Sahar Air Cargo | YAM Logistics',
 'Customs clearance in Mumbai: Nhava Sheva (INNSA1) sea cargo and Sahar air cargo (INBOM4), with our own sea and air offices. Licensed customs broker R-7/92.',
 'Customs clearance in Mumbai','CUSTOMS CLEARANCE · MUMBAI','Customs clearance in Mumbai,','sea and air.',
 'Mumbai has two clearing gateways: Nhava Sheva for sea cargo and Sahar for air cargo. We have an office for each, so the team that files your bill of entry is close to the cargo.',
 [('Sea cargo',['Our Mumbai sea office is at Room No. 51/52, 179 Commercial Chambers, Yusuf Meherali Road, Masjid Bunder. It handles Nhava Sheva imports and exports. See <a href="nhava-sheva-jnpt-customs-clearance" style="color:#0A6CC2">Nhava Sheva clearance</a>.']),
 ('Air cargo',['Our air cargo office is in the Sahar Air Cargo Complex, Andheri East, with a 24x7 desk. See <a href="air-cargo-clearance-mumbai-sahar" style="color:#0A6CC2">Mumbai Sahar air cargo clearance</a>.']),
 ('One team across Mumbai, Mundra and Delhi',['Cargo that lands in Mumbai may move to Delhi NCR, and cargo for Delhi may clear at Mundra. The same company files at each, so you deal with one team. See <a href="customs-clearance-india" style="color:#0A6CC2">customs clearance in India</a>.'])],
 [('Where is your Mumbai office?','We have two: a sea office at Masjid Bunder and an air cargo office at Sahar Air Cargo Complex, Andheri East.'),
  ('Do you clear at both Nhava Sheva and Sahar?','Yes, sea cargo at Nhava Sheva (INNSA1) and air cargo at Sahar (INBOM4).')],
 [('nhava-sheva-jnpt-customs-clearance','Nhava Sheva','Sea cargo.'),('air-cargo-clearance-mumbai-sahar','Mumbai Sahar','Air cargo.'),('contact','Contact','Office addresses.')])
